<script setup>
import {ref,computed,watch,onMounted,onUnmounted} from 'vue';
import {weekRange,monthRange,reportModel,reportFileName} from './blue/report-model.js';
import {renderReport} from './blue/report-canvas.js';
const props=defineProps({initial:{type:Object,default:()=>({})}}),emit=defineEmits(['close','data-export']);
const today=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const roleId=ref(props.initial.role_id||''),search=ref(''),range=ref(props.initial.range||'week'),week=ref(props.initial.date||today()),month=ref(props.initial.month||today().slice(0,7)),from=ref(props.initial.from||today().slice(0,7)+'-01'),to=ref(props.initial.to||today());
const confirmed=ref(false),page=ref(1),data=ref(null),loading=ref(false),error=ref(''),image=ref(null),generating=ref(false),imageError=ref(''),notice=ref(''),saving=ref(false),loadedAt=ref('');let generation=0;
const roles=computed(()=>data.value?.roles.filter(r=>r.selected||r.has_records)||[]),role=computed(()=>roles.value.find(r=>r.id===roleId.value));
const filteredRoles=computed(()=>roles.value.filter(r=>r.id===roleId.value||[r.label,r.server].join(' ').toLowerCase().includes(search.value.trim().toLowerCase())));
const period=computed(()=>range.value==='week'?weekRange(week.value):range.value==='month'?monthRange(month.value):{from:from.value,to:to.value});
const result=computed(()=>{if(!data.value)return {model:null,message:''};if(!role.value)return {model:null,message:'请选择要导出的角色（含有记录的历史角色）。'};if(!period.value)return {model:null,message:'请选择有效日期。'};try{return {model:reportModel(role.value,data.value.records,period.value.from,period.value.to,today()),message:''};}catch(e){return {model:null,message:e.message};}});
const model=computed(()=>result.value.model),pages=computed(()=>model.value?Math.ceil(model.value.days/31):1),currentPage=computed(()=>Math.max(1,Math.min(page.value,pages.value))),review=computed(()=>range.value==='period'||model.value?.needsReview),ready=computed(()=>!!model.value&&!loading.value&&!error.value&&(!review.value||confirmed.value));
const imageKey=computed(()=>JSON.stringify([roleId.value,range.value,period.value?.from,period.value?.to,currentPage.value,data.value?.revision,confirmed.value,loading.value,error.value]));
const canSave=computed(()=>ready.value&&image.value?.key===imageKey.value&&!generating.value&&!saving.value);
const reportKind=computed(()=>range.value==='week'?'周度':range.value==='month'?'月度':'自选日期');
watch([roleId,range,week,month,from,to],()=>{page.value=1;confirmed.value=false;notice.value='';},{flush:'sync'});
function clearImage(){if(image.value)URL.revokeObjectURL(image.value.url);image.value=null;}
watch([imageKey,ready],async()=>{const token=++generation;clearImage();imageError.value='';if(!ready.value){generating.value=false;return;}const key=imageKey.value;generating.value=true;try{const blob=await renderReport(model.value,reportKind.value,currentPage.value,loadedAt.value);if(token!==generation)return;image.value={blob,url:URL.createObjectURL(blob),key};}catch(e){if(token===generation)imageError.value=e.message;}finally{if(token===generation)generating.value=false;}},{immediate:true});
async function load(){if(saving.value)return;loading.value=true;error.value='';confirmed.value=false;try{const r=await window.pywebview.api.blue_records('load');if(!r.ok)throw Error(r.error);data.value=r.data;loadedAt.value=new Date().toISOString();if(!roleId.value&&roles.value.length===1)roleId.value=roles.value[0].id;}catch(e){error.value=e.message||'记录读取失败，暂不提供导出';}finally{loading.value=false;}}
async function download(){if(!canSave.value)return;saving.value=true;notice.value='';try{const blob=image.value.blob;const bytes=new Uint8Array(await blob.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));const filename=reportFileName(role.value.label,range.value==='week'?'周报':range.value==='month'?'月报':'日期报告',model.value.from,model.value.to,currentPage.value,pages.value);const r=await window.pywebview.api.blue_export({kind:'png',content:btoa(binary),filename});if(!r.ok)throw Error(r.error);notice.value=r.data.cancelled?'已取消下载':`已保存第 ${currentPage.value} / ${pages.value} 张 PNG。`;}catch(e){notice.value=e.message||'保存失败，请重试';}finally{saving.value=false;}}
async function copy(){if(!canSave.value)return;try{if(!navigator.clipboard?.write||typeof ClipboardItem==='undefined')throw Error();await navigator.clipboard.write([new ClipboardItem({'image/png':image.value.blob})]);notice.value='图片已复制，可以粘贴发送。';}catch{notice.value='当前环境未允许复制图片，请下载 PNG 后发送。';}}
function close(){if(saving.value)return;emit('close');}
function canLeave(){if(saving.value){notice.value='正在保存图片，请稍候';return false;}return true;}
defineExpose({canLeave});onMounted(load);onUnmounted(()=>{generation++;clearImage();});
</script>
<template><Teleport to="body"><div class="blue-report-mask" @click.self="close" @keydown.esc.stop="close"><section class="blue-report-dialog" role="dialog" aria-modal="true" aria-label="导出蓝票战报"><header><div><small>蓝票记录 · 角色战报</small><h2>导出战报图片</h2></div><button aria-label="关闭战报导出" :disabled="saving" @click="close">×</button></header><div class="blue-report-body"><p class="report-help">沿用网页战报样式。周报按周一至周日，自然月按日历统计；可自选最多 366 天。只导出角色、区服和掉落，不含账号凭证。</p><div class="report-controls"><label>搜索角色 / 区服<input aria-label="查找战报角色" v-model="search" :disabled="saving" placeholder="输入关键词"></label><label>角色<select aria-label="战报角色" v-model="roleId" :disabled="loading||saving"><option value="">请选择角色（含历史）</option><option v-for="r in filteredRoles" :key="r.id" :value="r.id">{{r.label}} · {{r.server||'未设区服'}}{{r.selected?'':' · 历史'}}</option></select></label><label>报告范围<select aria-label="战报范围" v-model="range" :disabled="saving"><option value="week">周报</option><option value="month">自然月报</option><option value="period">自选日期</option></select></label><label v-if="range==='week'">选择周内任意一天<input aria-label="战报周日期" type="date" v-model="week" :disabled="saving"></label><label v-if="range==='month'">选择月份<input aria-label="战报月份" type="month" v-model="month" :disabled="saving"></label><template v-if="range==='period'"><label>开始日期（含当日）<input aria-label="战报开始日期" type="date" v-model="from" :disabled="saving"></label><label>结束日期（含当日）<input aria-label="战报结束日期" type="date" v-model="to" :disabled="saving"></label></template></div><p v-if="loading" role="status">正在读取本机记录…</p><p v-if="error" class="report-error" role="alert">{{error}} <button :disabled="saving" @click="load">重试读取</button></p><p v-if="result.message" class="report-help">{{result.message}}</p><template v-if="model"><p class="report-summary">{{model.from}} — {{model.to}} · 已知蓝票 {{model.total??'—'}} 张 · 道馆 {{model.dojo??'—'}} / 狭间 {{model.xiajian??'—'}}<template v-if="model.rows.some(r=>r.record?.mode==='xiajian')"> · 黑碎 {{model.fragments??'—'}} 片 · 黑蛋 {{model.eggs??'—'}} 个</template></p><label v-if="review" class="report-confirm"><input type="checkbox" v-model="confirmed" :disabled="saving">我已核对起止日期和记录归属</label><p class="report-help">未记录 {{model.missing}} 天 · 待补 {{model.pending}} 天 · 未知 {{model.unknown}} 次 · 未打 {{model.missed}} 次。未到日期单独标注；空白不当作零。欧非参考本地全部完整道馆记录。</p></template><div v-if="pages>1" class="report-pages"><button :disabled="currentPage<=1||saving" @click="page--">上一张</button><span>第 {{currentPage}} / {{pages}} 张 · 每张最多 31 天，汇总为全区间</span><button :disabled="currentPage>=pages||saving" @click="page++">下一张</button></div><p v-if="generating" role="status">正在生成高清图片…</p><p v-if="imageError" class="report-error" role="alert">{{imageError}}</p><img v-if="image&&image.key===imageKey&&ready" class="report-preview" :src="image.url" alt="角色蓝票战报预览"><p v-if="notice" class="report-notice" role="status">{{notice}}</p></div><footer><button class="secondary" :disabled="saving" @click="emit('data-export')">数据导出（CSV / JSON）</button><button class="secondary" :disabled="loading||saving" @click="load">刷新记录</button><span></span><button class="secondary" :disabled="!canSave" @click="copy">复制图片</button><button class="primary" :disabled="!canSave" @click="download">{{saving?'保存中…':pages>1?'下载PNG（当前张）':'下载PNG'}}</button></footer></section></div></Teleport></template>
<style scoped>
.blue-report-mask{position:fixed;inset:0;z-index:2000;background:#30271c66;display:flex;align-items:center;justify-content:center;padding:20px}.blue-report-dialog{width:min(100%,980px);max-height:calc(100dvh - 40px);display:flex;flex-direction:column;background:#fffcf6;border:1px solid #dfcfb9;border-radius:12px;box-shadow:0 20px 70px #2c251d30;overflow:hidden}.blue-report-dialog>header{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:17px 22px;border-bottom:1px solid #e5dacb}.blue-report-dialog header small{color:#9c8263;font-size:11px}.blue-report-dialog h2{margin:4px 0 0;font-size:21px}.blue-report-dialog header button{border:0;background:transparent;font-size:24px}.blue-report-body{min-height:0;overflow:auto;padding:12px 22px}.report-help{font-size:12px;color:#8c7965;line-height:1.8;margin:8px 0}.report-controls{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:14px 0}.report-controls label{display:flex;flex-direction:column;gap:6px;font-size:12px;color:#796951}.report-controls input,.report-controls select{width:100%;min-width:0;padding:9px 10px;border:1px solid #ddcbb4;border-radius:6px;background:#fffdf9;font:inherit}.report-summary{font-size:13px;line-height:1.8;color:#675640}.report-confirm{display:flex;align-items:center;gap:8px;padding:10px;background:#f6ecd8;border-radius:6px;font-size:12px}.report-preview{display:block;width:min(100%,560px);height:auto;margin:16px auto;border:1px solid #e5d8c5;border-radius:8px;box-shadow:0 3px 20px #785d3015}.report-pages{display:flex;align-items:center;justify-content:center;gap:10px;font-size:12px;color:#8a7459;margin:12px 0}.report-error{color:#a43c2c;font-size:12px}.report-notice{color:#507057;font-size:12px}.blue-report-dialog>footer{display:flex;align-items:center;gap:8px;border-top:1px solid #e5dacb;padding:12px 22px;background:#fffcf6}.blue-report-dialog footer>span{flex:1}@media(max-width:650px){.report-controls{grid-template-columns:1fr}.blue-report-mask{padding:8px}.blue-report-dialog{max-height:calc(100dvh - 16px)}.blue-report-dialog>footer{flex-wrap:wrap;padding:10px}}
</style>
